function `Post And Confirm`(msg: <inbox-[:Emails]->>) {
  deals = only(chat-[ch:Channels WHERE ch.Name == "deals"]->)
  if (deals == null) { fail("no #deals channel") }

  lines = msg.Subject == "urgent" ? ["A big one just landed.", "Worth a look today."] : ["A new company just landed."]
  sent  = map(lines, (line) => { return write deals-[:Messages]-> { Message: line } })

  map(sent, (m) => {
    write m-[:Replies]-> { Message: "✅ filed" }
  })
}

listen to inbox-[e:Emails WHERE e.Key == "intake"]-> fire `Post And Confirm`

