node Message {
  Body: <text>
  node Attachments {
    Name: <text>
    `Content Type`: <text>
  }
}

node Setting {
  mode: <text | null>
  limit: <number | null>
}

function `Snapshot`(m: <inbox-[:Emails]->>) {
  msg = graph<Message> {
    Body: m.Body
    Attachments: m-[a:Attachments]-> {
      Name: a.Name
      `Content Type`: a.`Content Type`
    }
  }
  copy = graph<Message> {
    Body: m.Body
    Attachments: m-[:Attachments]->
  }
  empty = graph<Setting> {}
  raw   = { mode: "fast", limit: 3 }
  cfg   = graph<Setting> { ...raw }
  loose = graph { title: m.Subject }
  msg-[a:Attachments]-> {
    write crm-[:Companies]-> { unique by (Name) Name: a.Name }
  }
}

