function `Label`(name: <text>, tags: <text[]>, cfg: <{ prefix: text, suffix?: text }>) {
  return "${cfg.prefix}${name} (${Text.join(tags, ", ")})"
}

function `Intake`(m: <inbox-[:Emails]->>) {
