function `Merge`(m: <inbox-[:Emails]->>) {
  base      = { stage: "Seed", source: "email" }
  row       = { ...base, stage: "Series A" }
  content   = [m.Body]
  companies = extract(content, Company, { tier: "careful" })
  merged    = map(companies, (c) => {
    details = extractOne([...content, Json.stringify(c)], Profile, { tier: "careful" })
    return { ...c, ...details }
  })
  map(merged, (d) => {
    write crm-[:Companies]-> {
      unique by (`Name`)
      Name:        d.name
      Description: "${row.stage}: ${coalesce(d.summary, "")}"
    }
  })
}

